const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
let idx = 0;
const N = parseInt(input[idx++]);
const M = parseInt(input[idx++]);
const K = parseInt(input[idx++]);

const edges = [];
for (let i = 0; i < M; i++) {
  const a = parseInt(input[idx++]) - 1;
  const b = parseInt(input[idx++]) - 1;
  const t = parseInt(input[idx++]);
  edges.push([a, b, t]);
}

class DSU {
  constructor(n) {
    this.parent = new Int32Array(n);
    this.size = new Int32Array(n);
    for (let i = 0; i < n; i++) {
      this.parent[i] = i;
      this.size[i] = 1;
    }
  }
  find(x) {
    let root = x;
    while (this.parent[root] !== root) {
      root = this.parent[root];
    }
    while (this.parent[x] !== x) {
      const next = this.parent[x];
      this.parent[x] = root;
      x = next;
    }
    return root;
  }
  union(a, b) {
    let ra = this.find(a);
    let rb = this.find(b);
    if (ra === rb) return false;
    if (this.size[ra] < this.size[rb]) {
      [ra, rb] = [rb, ra];
    }
    this.parent[rb] = ra;
    this.size[ra] += this.size[rb];
    return true;
  }
}

const dsuWater = new DSU(N);
let waterCycle = false;

for (const [a, b, t] of edges) {
  if (t === 1) {
    if (!dsuWater.union(a, b)) {
      waterCycle = true;
      break;
    }
  }
}

