  const dsuAll = new DSU(N);
  for (const [a, b, t] of edges) {
    dsuAll.union(a, b);
  }

  let components = 0;
  for (let i = 0; i < N; i++) {
    if (dsuAll.find(i) === i) components++;
  }

  const minRemovals = M - N + components;
  console.log(minRemovals <= K ? 'S' : 'N');
}
